// check if we have any free blocks
if (lfs->free.off == lfs->free.size) {
    return LFS_ERR_NOSPC;
}

// find next free block using lookahead buffer
while (true) {
    // find next candidate in lookahead buffer
    lfs_block_t off = lfs->free.off;
    lfs_block_t size = lfs_min(lfs->cfg->lookahead_size * 8, lfs->free.size - off);

    // scan lookahead buffer for free block
    for (lfs_block_t i = 0; i < size; i++) {
        lfs_block_t block = (lfs->free.begin + off + i) % lfs->block_count;

        // check if block is free in lookahead buffer
        lfs_size_t index = i / 32;
        lfs_size_t bit = i % 32;
        if (!(lfs->free.buffer[index] & (1U << bit))) {
            // found free block, update lookahead buffer
            lfs->free.buffer[index] |= (1U << bit);
            lfs->free.off += i + 1;

            // update wear leveling state
            lfs->free.begin = (lfs->free.begin + i + 1) % lfs->block_count;

            *block = block;
            return 0;
        }
    }

    // no free blocks in current lookahead window, move to next window
    lfs->free.off += size;

    // check if we've exhausted all blocks
    if (lfs->free.off >= lfs->free.size) {
        return LFS_ERR_NOSPC;
    }

    // refill lookahead buffer
    memset(lfs->free.buffer, 0, lfs->cfg->lookahead_size);

    // scan actual blocks for free ones
    for (lfs_block_t i = 0; i < size && lfs->free.off + i < lfs->free.size; i++) {
        lfs_block_t block = (lfs->free.begin + lfs->free.off + i) % lfs->block_count;

        // check if block is actually free
        if (lfs->free.ack <= block && block < lfs->free.ack + lfs->free.size) {
            lfs_size_t index = i / 32;
            lfs_size_t bit = i % 32;
            lfs->free.buffer[index] |= (1U << bit);
        }
    }
}

